tool_calls.arguments:
{"command": "kubectl run curl-test --rm -i --restart=Never --image=curlimages/curl:8.10.1 --command -- sh -c '
echo "--- via ingress (host app.example.com, /app):";
curl -s -o /tmp/out -w "code=%{http_code}\n" --max-time 8 --resolve app.example.com:80:10.96.200.191 http://app.example.com/app;
head -c 300 /tmp/out; echo;
echo "--- via ingress (host app.example.com, /):";
curl -s -o /dev/null -w "code=%{http_code}\n" --max-time 8 --resolve app.example.com:80:10.96.200.191 http://app.example.com/;
echo "--- via ingress (wrong host, /app):";
curl -s -o /dev/null -w "code=%{http_code}\n" --max-time 8 --resolve other.example.com:80:10.96.200.191 http://other.example.com/app;
' 2>&1 | tail -20"}

